const money = n => new Intl.NumberFormat('en-US', {style: 'currency', currency: 'USD'}).format((n || 0) / 100);
const all = queries.units.data || [];
const onHire = a => (a.bookings || []).some(r => r.status === 'Out');
const shelfUnits = all.filter(a => a.service_status === 'Ready' && !onHire(a));
const a = all.find(u => u.id === variables.unitId);
return {
  ready: shelfUnits.length,
  out: all.filter(onHire).length,
  shelf: shelfUnits.slice(0, 3).map(u => ({ name: u.name, meta: u.tag + ' · ' + money(u.rate_cents) + '/day' })),
  unit: a
    ? { eyebrow: a.tag + ' / ' + a.category, name: a.name, meta: [a.location, a.item_condition, onHire(a) ? 'On hire' : a.service_status].filter(Boolean).join(' · '), rate: money(a.rate_cents) }
    : { eyebrow: 'EQUIPMENT / RENTAL WORKSPACE', name: 'Choose a unit from inventory', meta: '', rate: money(0) },
  history: (a?.history || []).slice().reverse()
};
